# Replace the task program with a compact guide-and-nearest-object transform, then produce its grid.
new='''from collections import Counter, deque

def transform(grid):
    g=[row[:] for row in grid]; h,w=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    # Find the color with the strongest paired horizontal/vertical guide runs.
    best=None
    for color in set(v for row in g for v in row)-{bg}:
        hs=[]; vs=[]
        for r in range(h):
            c=0
            while c<w:
                if g[r][c]!=color: c+=1; continue
                a=c
                while c<w and g[r][c]==color: c+=1
                if c-a>=3: hs.append((c-a,r,a,c-1))
        for c in range(w):
            r=0
            while r<h:
                if g[r][c]!=color: r+=1; continue
                a=r
                while r<h and g[r][c]==color: r+=1
                if r-a>=3: vs.append((r-a,c,a,r-1))
        for hl,hr,ha,hb in hs:
            for vl,vc,va,vb in vs:
                gap=max(0,ha-vc,vc-hb-1)+max(0,va-hr,hr-vb-1)
                score=(hl*vl,-gap)
                if best is None or score>best[0]: best=(score,color,hr,vc)
    if best is None: return g
    _,color,r0,c0=best
    # Recolor the nearest non-guide object to the guide's corner.
    seen=set(); choices=[]
    for r in range(h):
        for c in range(w):
            if g[r][c] in (bg,color) or (r,c) in seen: continue
            old=g[r][c]; q=deque([(r,c)]); seen.add((r,c)); comp=[]
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==old:
                        seen.add((yy,xx)); q.append((yy,xx))
            d=min(abs(y-r0)+abs(x-c0) for y,x in comp)
            choices.append((d,comp))
    if choices:
        _,comp=min(choices,key=lambda z:z[0])
        for y,x in comp: g[y][x]=color
    return g
'''
